function loadFromHtml(html, baseUrl) {
  try {
    var doc = new DOMParser().parseFromString(html, "text/html");
    var base = doc.createElement("base");
    base.href = baseUrl || new URL("./", new URL(URL_, document.baseURI)).href;

    if (doc.head) {
      doc.head.insertBefore(base, doc.head.firstChild);
    } else {
      var head = doc.createElement("head");
      head.appendChild(base);
      doc.documentElement.insertBefore(head, doc.body || null);
    }

    var s = doc.createElement("script");
    s.textContent = "window.__PARENT_SVG_URL__ = " + JSON.stringify(location.href) + "; window.__PARENT_SVG_HASH__ = " + JSON.stringify(location.hash) + "; window.__PARENT_SVG_SEARCH__ = " + JSON.stringify(location.search) + ";";
    if (doc.head) doc.head.insertBefore(s, doc.head.firstChild);

    var fullHtml = "<!doctype html>\n" + doc.documentElement.outerHTML;
    var blob = new Blob([fullHtml], { type: "text/html" });
    var blobUrl = URL.createObjectURL(blob);
    frame.src = blobUrl;
  } catch (e) {
    frame.srcdoc = html;
  }
}

if (EMBEDDED_HTML) {
  loadFromHtml(decodeURIComponent(EMBEDDED_HTML), document.baseURI);
} else {
  try {
    var targetUrl = new URL(URL_, document.baseURI).href;
    fetch(targetUrl, { credentials: "same-origin" })
      .then(function(r) {
        if (!r.ok) throw new Error("HTTP " + r.status);
        return r.text();
      })
      .then(function(html) {
        loadFromHtml(html, new URL("./", targetUrl).href);
      })
      .catch(function(err) {
        frame.srcdoc = "<!doctype html><html><body style='color:#f88;background:#07090e;padding:20px;'><pre>" + String(err) + "</pre></body></html>";
      });
  } catch(err) {
    frame.srcdoc = "<!doctype html><html><body style='color:#f88;background:#07090e;padding:20px;'><pre>" + String(err) + "</pre></body></html>";
  }
}
